package ru.neverland.townyjustice;
import java.util.*;import java.util.concurrent.*;import org.bukkit.Bukkit;import org.bukkit.plugin.java.JavaPlugin;import ru.neverland.core.*;import static ru.neverland.townyjustice.JusticePayment.Step.*;
/** Caller-owned durable identity. A pending legacy bank call is never converted into a new treasury request. */
final class JusticeTreasury {
    private static final String PROVIDER="NeverLandTownyTreasuryPlus",CONTRACT="ru.neverland.townytreasury.api.TownyTreasuryApi";
    private final JavaPlugin plugin;private final JusticeRepository repository;private CompletionStage<?> active=CompletableFuture.completedFuture(null);private boolean closing;private int cursor;private long warned;
    JusticeTreasury(JavaPlugin plugin,JusticeRepository repository){this.plugin=plugin;this.repository=repository;}
    static boolean installed(){return Bukkit.getPluginManager().getPlugin(PROVIDER)!=null;}
    static boolean available(){try{ApiServices.require(PROVIDER,CONTRACT,"requestDebit","debitStatus","requestRefund","refundStatus");return true;}catch(RuntimeException unavailable){return false;}}
    boolean busy(){return !active.toCompletableFuture().isDone();}
    void pulse(long now,long retry){if(closing||busy()||repository.busy()||!repository.writable()||SuiteState.frozen(plugin.getName()))return;var candidates=repository.state().payments().values().stream().filter(p->p.route()==JusticePayment.Route.TREASURY&&p.step()!=COMPLETE&&p.step()!=CANCELLED).sorted(Comparator.comparing(JusticePayment::id)).toList();if(candidates.isEmpty())return;var p=candidates.get(Math.floorMod(cursor++,candidates.size()));try{advance(p,now,retry);}catch(Exception error){warn(error);}}
    private void advance(JusticePayment p,long now,long retry)throws Exception{var before=repository.state();var c=before.cases().get(p.caseId());if(c==null)throw new IllegalStateException("Платёж суда без дела");boolean refund=p.kind()==JusticePayment.Kind.BOUNTY_REFUND;
        if(p.step()==READY||refund&&p.step()==DEBITED){if(p.check()!=0&&now-p.check()<retry)return;track(save(before,c,p.step(refund?CREDIT_PENDING:DEBIT_PENDING,now)));return;}
        if(p.step()!=(refund?CREDIT_PENDING:DEBIT_PENDING))return;var api=ApiServices.require(PROVIDER,CONTRACT,refund?"requestRefund":"requestDebit",refund?"refundStatus":"debitStatus");String reason=reason(c,refund);Object raw;
        if(refund){var backing=before.payments().get(c.payment());if(backing==null||backing.route()!=JusticePayment.Route.TREASURY||backing.kind()!=JusticePayment.Kind.BOUNTY_FUND||backing.step()!=COMPLETE)throw new IllegalStateException("Нет подтверждённого обеспечения возврата");raw=api.invoke("requestRefund",new Class<?>[]{UUID.class,UUID.class,UUID.class,String.class,String.class},p.treasuryId(),backing.treasuryId(),c.issuer(),plugin.getName(),reason);}
        else raw=api.invoke("requestDebit",new Class<?>[]{UUID.class,UUID.class,String.class,String.class,long.class,String.class,UUID.class,String.class},p.treasuryId(),p.town(),"army","justice",p.amount(),reason,c.issuer(),plugin.getName());
        if(!(raw instanceof CompletionStage<?> response))throw new IllegalStateException("Казна не вернула подтверждаемую квитанцию");track(response.thenCompose(value->{try(var guard=SuiteState.guard()){if(!(value instanceof Map<?,?> row))return CompletableFuture.failedFuture(new IllegalStateException("Неверная квитанция казны"));verify(row,p,c,reason);if(closing)return CompletableFuture.completedFuture(null);var current=repository.get(p.id());if(!p.equals(current)||!c.equals(repository.state().cases().get(c.id())))return CompletableFuture.failedFuture(new IllegalStateException("Платёж суда изменился до ответа казны"));var state=repository.state();return switch(row.get("status").toString()){
            case "PAID"->{var completed=p.step(COMPLETE,System.currentTimeMillis());var settled=c.phase(refund?JusticeCase.Phase.CANCELLED:JusticeCase.Phase.WANTED);yield save(state,settled,completed).thenApply(saved->{if(!refund&&!closing){var target=Bukkit.getPlayer(c.subject());if(target!=null)SuiteScheduler.entity(plugin,target,()->target.sendMessage(ru.neverland.core.EditableMessages.text(JusticeTreasury.class, "§e[Городской суд] Оплаченный розыск объявлен. /justice wanted")));}return saved;});}
            case "REJECTED"->{if(refund)yield save(state,c,p.rejectedRefund(System.currentTimeMillis()));yield save(state,c.phase(JusticeCase.Phase.CANCELLED),p.step(CANCELLED,System.currentTimeMillis()));}
            case "PREPARED","INVOKING","REVIEW"->CompletableFuture.completedFuture(null);
            default->CompletableFuture.failedFuture(new IllegalStateException("Неизвестное состояние банковской квитанции"));
        };}}));
    }
    static String reason(JusticeCase c,boolean refund){return "Суд: "+(refund?"возврат резерва":"резерв награды")+" по делу "+c.id();}
    private void verify(Map<?,?> row,JusticePayment p,JusticeCase c,String reason){boolean refund=p.kind()==JusticePayment.Kind.BOUNTY_REFUND;var backing=refund?repository.get(c.payment()):null;if(!p.treasuryId().toString().equals(row.get("operation"))||!p.town().toString().equals(row.get("town"))||!"army".equals(row.get("category"))||!"justice".equals(row.get("source"))||!(row.get("cents") instanceof Long cents)||cents!=p.amount()||!c.issuer().toString().equals(row.get("actor"))||!plugin.getName().equals(row.get("owner"))||!reason.equals(row.get("reason"))||!(refund?"REFUND":"DEBIT").equals(row.get("kind"))||!Objects.equals(row.get("backingDebit"),refund?backing.treasuryId().toString():""))throw new IllegalStateException("Квитанция относится к другому платежу суда");}
    private CompletionStage<JusticeRepository.State> save(JusticeRepository.State before,JusticeCase c,JusticePayment p){var cases=new HashMap<>(before.cases());cases.put(c.id(),c);var payments=new HashMap<>(before.payments());payments.put(p.id(),p);return repository.commitAsync(before,new JusticeRepository.State(cases,payments,before.prisons()));}
    private void track(CompletionStage<?> stage){active=stage;stage.whenComplete((v,e)->{if(e!=null)warn(e);});}
    private void warn(Throwable error){long now=System.currentTimeMillis();if(now-warned>=60000){warned=now;plugin.getLogger().log(java.util.logging.Level.WARNING,"Платёж суда ожидает казну или сверку; новый ID не создаётся при неизвестном ответе",error);}}
    CompletionStage<Void> prepareClose(){closing=true;return active.handle((v,e)->null).thenCompose(v->repository.prepareClose());}
}
